/// <summary>
/// PaffH 25.08.20
/// clean up 
/// </summary>
/// <param name="sender">xFormRun</param>
/// <param name="e">FormEventArgs</param>
[FormEventHandler(formStr(FormControlPersonalization), FormEventType::Closing),
 SuppressBPWarning("BPParameterNotUsed","Parameter is required by the event interface")]
public static void FormControlPersonalization_OnClosing(xFormRun sender, FormEventArgs e)
{
    NDXAnalyseForm::cleanUp();
}

/// <summary>
/// PaffH 24.08.20
/// get datasource info.
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(FormControlPersonalization, NDXBtnShowQueryInfo), FormControlEventType::Clicked),
 SuppressBPWarning("BPParameterNotUsed","Parameter is required by the event interface")]
public static void NDXBtnShowQueryInfo_OnClicked(FormControl sender, FormControlEventArgs e)
{
    sender.enabled(false);
    NDXAnalyseForm::getDatasourceInfo();
    sender.enabled(true);
    info(strFmt("@NDX:NDXFormInfoCollected", NDXAnalyseForm::getInstance().parmFormRunCalledFrom().name()));
}
